"""Generate the self-contained WAH Rollout Analyzer HTML application."""

from __future__ import annotations

import json
import math
from pathlib import Path
from typing import Any, Sequence

from .analytics import comparison, error_analysis, public_episode, run_summary
from .parser import RunData, generated_at, load_run


def _json_for_html(value: Any) -> str:
    def clean(item: Any) -> Any:
        if isinstance(item, float) and not math.isfinite(item):
            return None
        if isinstance(item, dict):
            return {str(key): clean(child) for key, child in item.items()}
        if isinstance(item, (list, tuple)):
            return [clean(child) for child in item]
        return item

    return (
        json.dumps(clean(value), ensure_ascii=False, separators=(",", ":"), allow_nan=False)
        .replace("<", "\\u003c")
        .replace("\u2028", "\\u2028")
        .replace("\u2029", "\\u2029")
    )


def _payload(runs: list[RunData]) -> dict[str, Any]:
    run_rows = []
    all_episodes = []
    for index, run in enumerate(runs):
        summary = run_summary(run)
        episodes = [public_episode(row, index) for row in run.episodes]
        all_episodes.extend(episodes)
        run_rows.append(
            {
                "index": index,
                "label": run.label,
                "root_name": run.root.name,
                "checkpoint": run.checkpoint,
                "checkpoint_identity": run.checkpoint_identity,
                "policy_type": run.policy_type,
                "sidecar_type": run.sidecar_type,
                "execution_horizon": run.execution_horizon,
                "episodes_per_task": run.episodes_per_task,
                "task_order": run.task_order,
                "summary": summary,
                "errors": error_analysis(run),
                "latency": run.latency,
                "telemetry": [
                    {
                        key: value
                        for key, value in event.items()
                        if key
                        in {
                            "event",
                            "timestamp",
                            "monotonic_seconds",
                            "task",
                            "episode_index",
                            "seed",
                            "action_count",
                            "inference_latency_ms",
                            "simulation_fps",
                            "elapsed_seconds",
                            "phase",
                            "diagnostics",
                        }
                    }
                    for event in run.telemetry
                ],
                "warnings": run.warnings,
                "protocol": run.protocol,
                "source": run.source,
            }
        )
    compare = comparison(runs)
    return {
        "generated_at": generated_at(),
        "runs": run_rows,
        "episodes": all_episodes,
        "comparison": {
            "tasks": compare["tasks"],
            "protocol_warnings": compare["protocol_warnings"],
            "paired": compare["paired"],
            "matched": [
                {
                    "task": row["task"],
                    "seed": row["seed"],
                    "changed": row["changed"],
                    "transition": row["transition"],
                    "episodes": [
                        public_episode(episode, index)
                        for index, episode in enumerate(row["episodes"])
                    ],
                }
                for row in compare["matched"]
            ],
        },
    }


