def generate_report(
    run_dirs: Sequence[str | Path],
    output: str | Path,
    *,
    labels: Sequence[str] | None = None,
) -> Path:
    """Load one or more rollout directories and write one offline HTML report."""
    if not run_dirs:
        raise ValueError("At least one rollout directory is required.")
    if labels is not None and len(labels) != len(run_dirs):
        raise ValueError("The number of --label values must match the number of --run values.")
    destination = Path(output).expanduser().resolve()
    if destination.suffix.lower() != ".html":
        destination = destination / "index.html"
    destination.parent.mkdir(parents=True, exist_ok=True)
    runs = [
        load_run(path, label=labels[index] if labels else None, output_dir=destination.parent)
        for index, path in enumerate(run_dirs)
    ]
    document = _HTML.replace("__CSS__", _CSS).replace("__DATA__", _json_for_html(_payload(runs)))
    temporary = destination.with_suffix(destination.suffix + ".tmp")
    temporary.write_text(document, encoding="utf-8")
    temporary.replace(destination)
    return destination
